  function downloadReport(filename:string,headers:string[],records:(string|number|null|undefined)[][]){const csv=csvDocument([headers,...records]);const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);}
 async function exportPagedReport<T>(label:string,filename:string,headers:string[],fetchPage:(offset:number)=>PromiseLike<any>,mapRows:(items:T[])=> (string|number|null|undefined)[][]){
 if(!supabase||reportExportBusy)return;setReportExportBusy(label);setReportExportMessage('');
 try{let all:T[]=[];const seenPages=new Set<string>();for(let offset=0;offset<100000;offset+=100){const {data,error}=await fetchPage(offset);if(error)throw error;const batch=(data??[]) as T[];if(!batch.length)break;const fingerprint=JSON.stringify(batch);if(seenPages.has(fingerprint))throw new Error('The server repeated a report page. Export stopped to avoid an incomplete or endless download.');seenPages.add(fingerprint);all=all.concat(batch);if(all.length>100000)throw new Error('The report exceeds the 100,000-row export safety limit. Narrow the report filters and retry.');if(batch.length<100)break;if(offset===99900)throw new Error('The report reached the 100,000-row export safety limit. Narrow the report filters and retry.');}if(!all.length){setReportExportMessage('No '+label+' records are available to export.');return;}const rows=mapRows(all);downloadReport(filename,headers,rows);setReportExportMessage('Exported '+rows.length+' '+label+' records.');}
 catch(e){setReportExportMessage(e instanceof Error?e.message:'Could not export '+label+'.');}finally{setReportExportBusy('');}
}
