  if(!walletAdjustmentKey.current){const bytes=new Uint8Array(16);window.crypto.getRandomValues(bytes);walletAdjustmentKey.current=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
  setWalletAdjustmentBusy(true);setWalletAdjustmentMessage('');
  try{const{data,error}=await supabase.rpc('admin_adjust_member_wallet',{p_member_code:walletAdjustmentMember.trim(),p_wallet_type:walletAdjustmentType,p_direction:walletAdjustmentDirection,p_amount:amount,p_reason:walletAdjustmentReason.trim(),p_idempotency_key:walletAdjustmentKey.current});if(error)throw error;const result=(data??{}) as {balance_after?:number;adjustment_id?:string};walletAdjustmentKey.current='';setWalletAdjustmentMessage('Wallet adjustment saved. New balance: ₹'+Number(result.balance_after??0).toLocaleString('en-IN')+'.');setWalletAdjustmentAmount('');setWalletAdjustmentReason('');setRefresh(v=>v+1);}
