 const filteredWalletLedger=useMemo(()=>{const q=walletLedgerSearch.trim().toLowerCase();return walletTransactions.filter(x=>{const day=x.created_at.slice(0,10);const searchable=[x.member_code,x.wallet_type,x.transaction_type,x.direction,x.reference_type,x.reference_id,x.description].filter(Boolean).join(' ').toLowerCase();return(!q||searchable.includes(q))&&(!walletLedgerFrom||day>=walletLedgerFrom)&&(!walletLedgerTo||day<=walletLedgerTo);});},[walletTransactions,walletLedgerSearch,walletLedgerFrom,walletLedgerTo]);
